      `ROLLUP sheet=${sheet} by=uma person=Ada claimed=1.00 due-total=1.00`,
      `TOTALS sheet=${sheet} by=uma claimed-total=1.00 due-total=1.00`,
      `SETTING_CHANGED sheet=${sheet} by=uma key=period-numbering-from value=2026-03-16`,
      `CLAIM_OPENED sheet=${sheet} by=uma person=Ada amount=2.00 date=2026-03-15 number=2`,
      `ROLLUP sheet=${sheet} by=uma person=Ada claimed=3.00 due-total=2.00`,
      `TOTALS sheet=${sheet} by=uma claimed-total=3.00 due-total=2.00`,
      `SETTING_CHANGED sheet=${sheet} by=uma key=period-numbering-from value=2026-03-15`,
      `CLAIM_OPENED sheet=${sheet} by=uma person=Ada amount=3.00 date=2026-03-25 number=X-1`,
      `ROLLUP sheet=${sheet} by=uma person=Ada claimed=6.00 due-total=3.00`,
      `TOTALS sheet=${sheet} by=uma claimed-total=6.00 due-total=3.00`,
      `CLAIM_OPENED sheet=${sheet} by=uma person=Ada amount=4.00 date=2026-03-06 number=P1-1`,
      `ROLLUP sheet=${sheet} by=uma person=Ada claimed=10.00 due-total=4.00`,
      `TOTALS sheet=${sheet} by=uma claimed-total=10.00 due-total=4.00`,
      `CLAIM_OPENED sheet=${sheet} by=uma person=Ada amount=5.00 date=2026-03-12 number=P2-1`,
      `ROLLUP sheet=${sheet} by=uma person=Ada claimed=15.00 due-total=5.00`,
      `TOTALS sheet=${sheet} by=uma claimed-total=15.00 due-total=5.00`,
      `SETTING_CHANGED sheet=${sheet} by=uma key=period-numbering-from value=`,
      `CLAIM_OPENED sheet=${sheet} by=uma person=Ada amount=6.00 date=2026-03-15 number=3`,
      `ROLLUP sheet=${sheet} by=uma person=Ada claimed=21.00 due-total=6.00`,
      `TOTALS sheet=${sheet} by=uma claimed-total=21.00 due-total=6.00`
    ]);
  });
  test("numbering per period scenario 1", { tag: '@functionality' }, async ({ browser }) => {
    const sheet = ui.sheetId();
    const pg_uma = await ui.userPage(browser, "uma", sheet);
    await ui.setToday(pg_uma, "2026-03-20");
