151	                    "The user who opened a claim cannot settle it");
152	        }
153	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
154	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
155	        // a claim bound by a statement settles at its bound figure, its late charge frozen in
156	        BigDecimal settling = to == ClaimStatus.SETTLED ? shownDueOf(claim, person) : null;
157	        if (to == ClaimStatus.SETTLED && !settings.maySettle(sheetId, user, settling)) {
158	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
159	                    "A clerk cannot settle a claim whose due is above the clerk limit");
160	        }
161	        RollupService.Snapshot before = rollup.snapshot(sheetId);
162	        // a voided claim keeps its number (never reused), and the VOIDED record carries it
163	        Integer number = claim.getNumber();
164	        claim.setStatus(to);
165	        if (to == ClaimStatus.OPEN) {
166	            number = sheets.nextClaimNumber(sheetId);
167	            claim.setNumber(number);
168	            claim.setOpenedBy(user);
169	        } else if (to == ClaimStatus.SETTLED) {
170	            claim.setSettledDue(settling);
171	        }
172	        claims.flush();
173	        String event = switch (to) {
174	            case OPEN -> "CLAIM_OPENED";
175	            case SETTLED -> "CLAIM_SETTLED";
176	            case VOID -> "CLAIM_VOIDED";
177	            case DRAFT -> throw new IllegalArgumentException("A claim cannot return to DRAFT");
178	        };
179	        if (to == ClaimStatus.SETTLED) {
180	            BigDecimal due = claim.getSettledDue();
181	            record(event, user, person, claim, number, " due=" + (due == null ? "n/a" : due.toPlainString()));
182	        } else {
183	            record(event, user, person, claim, number);
184	        }
185	        rollup.recordChanges(sheetId, user, before);
186	        return claim;
187	    }
