189	    /** Take a statement of a person: record their due-total now, and bind each of their claims
190	     *  that counts (OPEN or SETTLED, of a held person only SETTLED) to its figure now; the others
191	     *  are left unbound. */
192	    @Transactional
193	    public Statement statement(String sheetId, String user, long personId) {
194	        Person person = people.findForUpdate(personId, sheetId)
195	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
196	        LocalDate today = sheets.today(sheetId);
197	        List<Claim> theirs = claims.findByPersonForUpdate(personId, sheetId);
198	        RollupService.Snapshot before = rollup.snapshot(sheetId);
199	        List<Claim> counted = theirs.stream().filter(c -> counts(c, person)).toList();
200	        BigDecimal dueTotal = dueTotalOf(counted, person, today);
201	        for (Claim c : theirs) {
202	            if (counts(c, person)) {
203	                // the statement binds the figure; the late charge keeps following the sheet's today
204	                c.bind(c.getSettledDue() != null ? c.getSettledDue() : figureOf(c, person));
205	            } else {
206	                c.unbind();
207	            }
208	        }
209	        claims.flush();
210	        statements.saveAndFlush(new PersonStatement(sheetId, personId, dueTotal, counted.size(), today, user));
211	        audit.recordOnCommit("STATEMENT sheet=" + sheetId + " by=" + user + " name=" + person.getName()
212	                + " due-total=" + (dueTotal == null ? "n/a" : dueTotal.toPlainString()) + " claims=" + counted.size());
213	        rollup.recordChanges(sheetId, user, before);
214	        return new Statement(person, StatementSummary.of(statements.findByPersonIdOrderByIdAsc(personId)), theirs);
215	    }
