217	    /** Refuse (423) a change to a claim dated in a closed period, holding the sheet locked until
218	     *  the transaction ends so a period cannot be closed meanwhile. */
219	    private void refuseIfClosed(String sheetId, LocalDate date) {
220	        sheets.lock(sheetId);
221	        periods.refuseIfClosed(sheetId, date);
222	    }
223	
224	    /** The number a claim of the amount corrects: none unless the amount is negative, when it must
225	     *  be the number of a SETTLED claim of the same person, or the claim is refused (422). */
226	    private Integer correctedBy(String sheetId, long personId, BigDecimal amount, Integer corrects) {
227	        if (amount.signum() >= 0) {
228	            return null;
229	        }
230	        if (corrects == null
231	                || !claims.existsBySheetIdAndPersonIdAndNumberAndStatus(sheetId, personId, corrects, ClaimStatus.SETTLED)) {
232	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
233	                    "A negative amount must correct a settled claim of the same person");
234	        }
235	        return corrects;
236	    }
237	
238	    /** Refuse (422) a claim dated after its person's retirement date. */
239	    private static void refuseIfRetired(Person person, LocalDate date) {
240	        if (person.retiredBefore(date)) {
241	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
242	                    "The date is after the person's retirement date");
243	        }
244	    }
245	
246	    /** Whether a claim counts toward claimed and due totals: only OPEN and SETTLED ones do, and
247	     *  of a held person only SETTLED ones. */
248	    private static boolean counts(Claim c, Person person) {
249	        return c.getStatus() == ClaimStatus.SETTLED
250	                || (c.getStatus() == ClaimStatus.OPEN && !person.isHeld());
251	    }
252	
253	    /** The due a claim shows: the due fixed when it was settled, else its figure with its late
254	     *  charge on top. */
255	    private BigDecimal shownDueOf(Claim claim, Person person) {
256	        if (claim.getSettledDue() != null) {
257	            return claim.getSettledDue();
258	        }
259	        return LateCharge.of(sheets.find(claim.getSheetId())).addTo(claim, figureOf(claim, person), roundingOf(claim));
260	    }
261	
262	    /** A claim's figure before any late charge: the one a statement bound it to (null: n/a), else
263	     *  its live due. */
264	    private BigDecimal figureOf(Claim claim, Person person) {
265	        return claim.isStated() ? claim.getStatedDue() : dueOf(claim, person);
266	    }
267	
268	    /** A person's due-total: the sum of the dues their counting claims show (n/a ones skipped);
269	     *  null (n/a) when their grade in force on the sheet's today has no rate then, unless a claim
270	     *  shows a due (a fixed or bound one, or one at the rate of the grade they had on its date). */
271	    private BigDecimal dueTotalOf(List<Claim> counted, Person person, LocalDate today) {
272	        List<BigDecimal> dues = counted.stream().map(c -> shownDueOf(c, person)).filter(d -> d != null).toList();
273	        if (rates.findInForce(person.getSheetId(), person.gradeOn(today), today).isEmpty() && dues.isEmpty()) {
274	            return null;
275	        }
276	        return dues.stream().reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
277	    }
278	
279	    /** The claim's amount times the rate, in force on the claim's date, of its person's grade then, divided by
280	     *  100, rounded as its rounding policy has it, raised to the sheet's floor (a correction's never is); null with no rate in force then. */
281	    private BigDecimal dueOf(Claim claim, Person person) {
282	        BigDecimal floor = sheets.floor(claim.getSheetId());
283	        return rates.findInForce(claim.getSheetId(), person.gradeOn(claim.getDate()), claim.getDate())
284	                .map(Rate::getPct)
285	                .map(pct -> claim.getAmount().multiply(pct).divide(BigDecimal.valueOf(100), 2, roundingOf(claim)))
286	                .map(due -> claim.isCorrection() ? due : due.max(floor))
287	                .orElse(null);
288	    }
289	
290	    /** How the claim's live figures round: by the sheet's policy date against its date, or for a
291	     *  correction the date of the claim it corrects. */
292	    private RoundingMode roundingOf(Claim claim) {
293	        LocalDate on = claim.getCorrects() == null ? claim.getDate()
294	                : claims.findFirstBySheetIdAndPersonIdAndNumber(claim.getSheetId(), claim.getPersonId(), claim.getCorrects())
295	                        .map(Claim::getDate).orElse(claim.getDate());
296	        return Rounding.of(sheets.find(claim.getSheetId())).on(on);
297	    }
298	
299	    private void record(String event, String user, Person person, Claim claim) {
300	        record(event, user, person, claim, claim.getNumber());
301	    }
302	
303	    /** Amounts are written as the screen shows them (two decimals), dates as yyyy-mm-dd. */
304	    private void record(String event, String user, Person person, Claim claim, Integer number) {
305	        record(event, user, person, claim, number, "");
306	    }
307	
308	    private void record(String event, String user, Person person, Claim claim, Integer number, String extra) {
309	        audit.recordOnCommit(event + " sheet=" + claim.getSheetId() + " by=" + user
310	                + " person=" + person.getName() + " amount=" + claim.getAmount().setScale(2).toPlainString()
311	                + " date=" + claim.getDate() + (number != null ? " number=" + number : "") + extra);
312	    }
313	
314	    private static String noteOf(String note) {
315	        return note == null ? "" : note.trim();
316	    }
317	}
