532	    @Transactional
533	    public Sheet load(String id, String user) {
534	        return sheets.findById(id).orElseGet(() -> {
535	            try {
536	                return sheets.saveAndFlush(new Sheet(id, user, LocalDate.now()));
537	            } catch (DataIntegrityViolationException e) {
