569	    @Transactional(readOnly = true)
570	    public int terms(String id) {
571	        return sheets.findById(id).map(Sheet::getTerms).orElse(Sheet.DEFAULT_TERMS);
572	    }
573	
574	    /** The sheet's late percent: an overdue claim's due gains it for every full 30 days overdue. */
575	    @Transactional(readOnly = true)
576	    public BigDecimal latePct(String id) {
577	        return sheets.findById(id).map(Sheet::getLatePct).orElse(Sheet.DEFAULT_LATE_PCT);
578	    }
