580	    /** Take the sheet's next claim number (1 for the first), holding the sheet locked until the
581	     *  transaction ends so numbers are never shared and, if it rolls back, never skipped. */
582	    @Transactional
583	    public int nextClaimNumber(String id) {
584	        Sheet sheet = sheets.findForUpdate(id).orElseThrow();
585	        int number = sheet.nextClaimNumber();
586	        sheets.flush();
587	        return number;
