597	    /** Change the sheet's today (the sheet is created first if it was never loaded); it has no
598	     *  audit line of its own, only the figures it moves. */
599	    @Transactional
600	    public Sheet setToday(String id, String user, LocalDate today) {
601	        Sheet sheet = load(id, user);
602	        RollupService.Snapshot before = rollup.snapshot(id);
